/**
 * Regenerates src/content/coachEd/conditions/index.generated.ts, the light
 * search index the app loads up front. Run: npx tsx scripts/coach-ed-gen-index.ts
 * The validator fails if the generated file is stale.
 */
import { writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { CONDITION_FILES, CONDITION_LOADERS } from '../src/content/coachEd/conditions/files.ts'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const out = join(root, 'src/content/coachEd/conditions/index.generated.ts')

export async function buildIndexSource(): Promise<string> {
  const rows: Record<string, unknown>[] = []
  for (const file of CONDITION_FILES) {
    const list = await CONDITION_LOADERS[file]()
    for (const c of list) {
      rows.push({
        id: c.id,
        name: c.name,
        aliases: c.aliases,
        regions: c.regions,
        tissues: c.tissues,
        tags: c.tags,
        urgency: c.urgency,
        completeness: c.completeness,
        review: c.review,
        file,
      })
    }
  }
  return `// Generated by scripts/coach-ed-gen-index.ts. Do not edit by hand.
import type { ConditionSummary } from '../types'
import type { ConditionFile } from './files'

export type ConditionIndexRow = ConditionSummary & { file: ConditionFile }

export const CONDITION_INDEX: ConditionIndexRow[] = ${JSON.stringify(rows, null, 2)}
`
}

if (process.argv[1] && process.argv[1].endsWith('coach-ed-gen-index.ts')) {
  const src = await buildIndexSource()
  writeFileSync(out, src)
  console.log(`wrote ${out}`)
}
